//! TODO Reviewed ??-??-2026.

/// Use code generated by a build script that ran a vendored `protoc`.
mod echo;
/// Serve a tonic service to browsers with gRPC-Web.
mod grpc_web;
/// This example shows how to create a simple gRPC server using the `tonic`
mod tonic;
/// This example shows how to create a simple gRPC client using the `tonic`
mod tonic_client;

/// Runs the grpc example.
fn main() -> anyhow::Result<()> {
    // The CORS settings that `grpc_web::serve` applies for browser clients:
    let _cors = grpc_web::cors();
    tonic::run()?;
    Ok(())
}

/// Verifies that the gRPC server example.
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[ignore = "serves on [::1]:50051 until stopped"]
    fn main_runs() {
        main().expect("the example should run");
    }
}
